 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; pub fn analyze_file_macros (file_path : & Path) -> Result < HashMap < String , Vec < Term > > > { let mut content = fs :: read_to_string (file_path) . with_context (| | format ! ("Failed to read file: {}" , file_path . display ())) ? ; if content . trim_end () . ends_with (". sig") { let trimmed_len = content . trim_end () . len () ; content . truncate (trimmed_len - ". sig" . len ()) ; } content = content . replace ("# [" , "#[") ; content = content . replace (" } " , "}\n") ; content = content . replace (" ] " , "]\n") ; let ast = parse_file (& content) . with_context (| | format ! ("Failed to parse Rust file: {}" , file_path . display ())) ? ; let mut macro_terms : HashMap < String , Vec < Term > > = HashMap :: new () ; for item in ast . items { if let syn :: Item :: Fn (func) = item { let is_pub = matches ! (func . vis , syn :: Visibility :: Public (_)) ; if func . sig . ident . to_string () . ends_with ("_impl") && is_pub { let mut collector = TermCollector :: default () ; collector . visit_item_fn (& func) ; macro_terms . insert (func . sig . ident . to_string () , collector . terms) ; } } } Ok (macro_terms) }